function validate([nums1, nums2]) {
  for (const [name, nums] of [['nums1', nums1], ['nums2', nums2]]) {
    if (!Array.isArray(nums) || nums.length < 1 || nums.length > 100000) return `${name} needs 1 to 10^5 values.`;
    if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 100000)) return `Each value of ${name} is an integer from 1 to 10^5.`;
    for (let k = 1; k < nums.length; k++) if (nums[k] > nums[k - 1]) return `${name} must be non-increasing.`;
  }
  return null;
}

