function maxDistance(nums1, nums2) {
  let i = 0;
  let j = 0;
  let best = 0;

  while (i < nums1.length && j < nums2.length) {
    if (nums1[i] <= nums2[j]) {
      best = Math.max(best, j - i);
      j++;
    } else {
      i++;
    }
  }
  return best;
}

