function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const make = (length, lo, hi) => Array.from({ length }, () => int(lo, hi)).sort((a, b) => b - a);
  if (size === 'large') {
    const shape = int(0, 2);
    const nums1 = make(int(1500, 2000), 1, 100000);
    const nums2 = shape === 0 ? make(2000, 1, 100000) : shape === 1 ? make(2000, 1, 60000) : make(int(1500, 2000), 40000, 100000);
    return [nums1, nums2];
  }
  const span = rand() < 0.5 ? 4 : 20;
  return [make(int(1, 7), 1, span), make(int(1, 7), 1, span)];
